with valid as (select *, coalesce(budget, 0) as budget_filled from departments where location in ('Berlin', 'New York', 'Chiang Mai')) select case when budget_filled >= 86 then 'PREMIUM' else 'STANDARD' end as budget_filled_tier, avg(budget) as avg_budget, round(avg(budget_filled), 2) as avg_budget_filled, round(sum(budget) / nullif(count(case when location = 'Bangkok' then 1 end), 0), 2) as budget_per_bangkok, count(*) as cnt from valid group by case when budget_filled >= 86 then 'PREMIUM' else 'STANDARD' end having budget_per_bangkok > 0
